import { useCallback } from 'react';
import { useIntl } from 'react-intl';

import pdfFile from 'assets/pdf/test.pdf';
import { StickyScrollWithFilters } from 'components';
import { StyledGridContainer, StyledGridItem } from 'shared/Styles';

import { PdfSlideViewer } from './components/PdfSlideViewer';
import { PDF_VIEWER_PAGE_NAME } from './constants';
import { StyledPdfViewerContent } from './PdfViewer.styles';

export const PdfViewer: React.FC = () => {
  const { formatMessage } = useIntl();

  const handleDownload = useCallback(() => {
    const link = document.createElement('a');
    link.href = pdfFile;
    link.download = 'pdf-report.pdf';
    document.body.appendChild(link);
    link.click();
    link.remove();
  }, []);

  return (
    <>
      <StickyScrollWithFilters
        filter={{
          pageName: PDF_VIEWER_PAGE_NAME,
          filtersApiKeys: [],
          hidden: true,
        }}
        breadcrumbs={{
          pageList: [
            {
              href: '/value-creation',
              pageName: formatMessage({
                id: 'Pillars.pageName.valueCreation',
              }),
            },
            {
              href: PDF_VIEWER_PAGE_NAME,
              pageName: formatMessage({ id: 'Sidebar.pdfViewer' }),
            },
          ],
          showIcon: true,
        }}
        isInPRPages
      />

      <StyledGridContainer data-testid="pdf-viewer" isInPRPages>
        <StyledGridItem
          data-testid="pdf-viewer-grid-item"
          xs={12}
          sm={12}
          md={12}
          lg={12}
          xl={12}
          style={{ marginTop: 24 }}
        >
          <StyledPdfViewerContent>
            <PdfSlideViewer
              pdfUrl={pdfFile}
              onDownload={handleDownload}
              dataTestId="pdf-viewer-slide"
            />
          </StyledPdfViewerContent>
        </StyledGridItem>
      </StyledGridContainer>
    </>
  );
};
